import React, { useRef, useMemo, useState, useEffect } from "react";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
  TooltipPositioner
} from "chart.js";

// Register required Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

// OPTIONAL: if you want zoom/pan install and register chartjs-plugin-zoom
// import zoomPlugin from 'chartjs-plugin-zoom';
// ChartJS.register(zoomPlugin);

// Small utility: safe number formatter (INR by default)
const formatNumber = (v, opts = { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }) => {
  try {
    return new Intl.NumberFormat('en-IN', opts).format(v);
  } catch (e) {
    return String(v);
  }
};

const movingAverage = (arr, windowSize) => {
  if (!arr || arr.length === 0) return [];
  const res = [];
  let sum = 0;
  for (let i = 0; i < arr.length; i++) {
    sum += arr[i] || 0;
    if (i >= windowSize) {
      sum -= arr[i - windowSize] || 0;
      res.push(sum / windowSize);
    } else if (i === windowSize - 1) {
      res.push(sum / windowSize);
    } else {
      res.push(null);
    }
  }
  return res;
};

// small plugin that draws a vertical hover line and an indicator dot on each visible dataset
const hoverLinePlugin = {
  id: 'hoverLine',
  afterDraw: (chart) => {
    const { ctx, chartArea, tooltip } = chart;
    if (!tooltip || tooltip.opacity === 0) return;
    const x = tooltip.caretX;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(x, chartArea.top);
    ctx.lineTo(x, chartArea.bottom);
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = 'rgba(0,0,0,0.15)';
    ctx.stroke();
    ctx.restore();
  }
};

export default function ChartView({ chart }) {
  const chartRef = useRef(null);
  const [smoothing, setSmoothing] = useState(true);
  const [showSMA, setShowSMA] = useState(true);
  const [smaWindow, setSmaWindow] = useState(7);

  useEffect(() => {
    // reset SMA window if data is short
    if (!chart || !chart.price) return;
    const n = chart.price.series.length || 0;
    if (smaWindow > Math.max(1, Math.floor(n / 2))) {
      setSmaWindow(Math.max(3, Math.floor(n / 10)));
    }
  }, [chart]);

  if (!chart || !chart.price || !Array.isArray(chart.price.labels) || chart.price.labels.length === 0) {
    return (
      <div className="text-muted small">No chart data available. Ask about an area (e.g. "Analyze Wakad") or upload a dataset.</div>
    );
  }

  const price = chart.price;
  const demand = chart.demand;

  // memoize gradient creation so it's stable across renders
  const gradients = useMemo(() => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const g1 = ctx.createLinearGradient(0, 0, 0, 200);
    g1.addColorStop(0, 'rgba(99,102,241,0.9)');
    g1.addColorStop(1, 'rgba(99,102,241,0.15)');

    const g2 = ctx.createLinearGradient(0, 0, 0, 200);
    g2.addColorStop(0, 'rgba(16,185,129,0.9)');
    g2.addColorStop(1, 'rgba(16,185,129,0.12)');

    return { g1, g2 };
  }, []);

  const priceSMA = useMemo(() => (showSMA ? movingAverage(price.series, Math.max(1, Math.round(smaWindow))) : []), [price.series, showSMA, smaWindow]);

  const datasets = [];

  datasets.push({
    label: 'Price',
    data: price.series,
    yAxisID: 'y',
    tension: smoothing ? 0.3 : 0.0,
    borderColor: (context) => {
      const chart = context.chart;
      const { ctx, chartArea } = chart;
      if (!chartArea) return 'rgba(99,102,241,1)';
      const grad = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
      grad.addColorStop(0, 'rgba(99,102,241,1)');
      grad.addColorStop(1, 'rgba(99,102,241,0.6)');
      return grad;
    },
    backgroundColor: gradients.g1,
    fill: true,
    pointRadius: 2,
    pointHoverRadius: 6,
    borderWidth: 2,
    spanGaps: true,
    parsing: false // data is already numeric array
  });

  if (showSMA) {
    datasets.push({
      label: `${smaWindow}-period SMA`,
      data: priceSMA,
      yAxisID: 'y',
      tension: 0.25,
      borderDash: [6, 4],
      borderColor: 'rgba(99,102,241,0.9)',
      pointRadius: 0,
      borderWidth: 1.5,
      fill: false
    });
  }

  if (demand && Array.isArray(demand.labels) && demand.labels.length > 0) {
    datasets.push({
      label: 'Demand',
      data: demand.series,
      yAxisID: 'y1',
      tension: smoothing ? 0.2 : 0.0,
      borderColor: (context) => {
        const chart = context.chart;
        const { ctx, chartArea } = chart;
        if (!chartArea) return 'rgba(16,185,129,1)';
        const grad = ctx.createLinearGradient(0, chartArea.top, 0, chartArea.bottom);
        grad.addColorStop(0, 'rgba(16,185,129,1)');
        grad.addColorStop(1, 'rgba(16,185,129,0.6)');
        return grad;
      },
      backgroundColor: gradients.g2,
      pointStyle: 'circle',
      pointRadius: 3,
      pointHoverRadius: 6,
      borderWidth: 2,
      fill: false
    });
  }

  const data = {
    labels: price.labels,
    datasets
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 400 },
    interaction: { mode: 'index', intersect: false },
    plugins: {
      legend: {
        display: true,
        position: 'top',
        labels: { usePointStyle: true, padding: 16 }
      },
      tooltip: {
        enabled: true,
        mode: 'index',
        intersect: false,
        padding: 10,
        callbacks: {
          title: (items) => {
            return items[0]?.label || '';
          },
          label: (context) => {
            const label = context.dataset.label || '';
            const value = context.parsed.y;
            return `${label}: ${formatNumber(value, { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })}`;
          },
          afterBody: (items) => {
            // Show change from previous point for the first dataset only
            const first = items[0];
            if (!first) return '';
            const idx = first.dataIndex;
            const ds = first.dataset;
            if (!ds || !ds.data) return '';
            const cur = ds.data[idx];
            const prev = idx > 0 ? ds.data[idx - 1] : null;
            if (prev == null || prev === 0) return '';
            const pct = ((cur - prev) / prev) * 100;
            const sign = pct >= 0 ? '+' : '';
            return `Change: ${sign}${pct.toFixed(2)}%`;
          }
        }
      },
      // custom plugin will draw a subtle background and corner title
      title: {
        display: false
      }
    },
    scales: {
      x: {
        display: true,
        ticks: { maxRotation: 0, autoSkip: true, maxTicksLimit: 10 }
      },
      y: {
        type: 'linear',
        display: true,
        position: 'left',
        ticks: {
          callback: (v) => formatNumber(v, { style: 'currency', currency: 'INR', maximumFractionDigits: 0 })
        }
      },
      y1: {
        type: 'linear',
        display: !!(demand && demand.labels && demand.labels.length > 0),
        position: 'right',
        grid: { drawOnChartArea: false },
        ticks: {
          callback: (v) => `${Math.round(v)} units`
        }
      }
    },
    // register our hover line plugin locally
    pluginsOrder: ['hoverLine']
  };

  // small helper to download CSV
  const downloadCSV = () => {
    const labels = data.labels || [];
    const rows = [
      ['label', ...labels]
    ];
    data.datasets.forEach(ds => {
      rows.push([ds.label, ...ds.data.map(v => (v == null ? '' : v))]);
    });
    const csv = rows.map(r => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'chart-data.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const exportPNG = () => {
    const chartInstance = chartRef.current?.chartInstance || chartRef.current?.ctx || chartRef.current?.chart;
    // react-chartjs-2 v4 exposes the chart as chartRef.current
    const chartObj = chartRef.current?._chart || chartRef.current?.chart;
    try {
      const url = chartRef.current?.toBase64Image();
      if (!url) return;
      const a = document.createElement('a');
      a.href = url;
      a.download = 'chart.png';
      a.click();
    } catch (e) {
      console.error('Export error', e);
    }
  };

  // register plugin on mount/unmount
  useEffect(() => {
    ChartJS.register(hoverLinePlugin);
    return () => {
      try {
        ChartJS.unregister(hoverLinePlugin);
      } catch (e) {}
    };
  }, []);

  return (
    <div className="p-4 bg-white rounded-2xl shadow-md">
      <div className="flex items-center justify-between mb-3">
        <div>
          <h3 className="text-lg font-semibold">Price & Demand</h3>
          <p className="text-sm text-slate-500">Interactive chart with SMA, smoothing and export tools</p>
        </div>
        <div className="flex items-center gap-2">
          <button
            className="px-3 py-1 text-sm rounded-md border" 
            onClick={() => setSmoothing(s => !s)}
            title="Toggle smoothing"
          >
            {smoothing ? 'Smoothing: ON' : 'Smoothing: OFF'}
          </button>
          <button
            className="px-3 py-1 text-sm rounded-md border"
            onClick={() => setShowSMA(s => !s)}
            title="Toggle SMA"
          >
            {showSMA ? 'SMA: ON' : 'SMA: OFF'}
          </button>
          <button className="px-3 py-1 text-sm rounded-md border" onClick={exportPNG}>Export PNG</button>
          <button className="px-3 py-1 text-sm rounded-md border" onClick={downloadCSV}>Download CSV</button>
        </div>
      </div>

      <div className="flex gap-4 mb-3 items-center">
        <label className="flex items-center gap-2 text-sm text-slate-600">
          SMA window
          <input
            type="range"
            min={3}
            max={Math.max(3, Math.floor(price.series.length / 2))}
            value={smaWindow}
            onChange={(e) => setSmaWindow(Number(e.target.value))}
          />
          <span className="w-10 text-right">{smaWindow}</span>
        </label>
      </div>

      <div style={{ height: 360 }}>
        <Line ref={chartRef} data={data} options={options} plugins={[hoverLinePlugin]} />
      </div>

      <div className="mt-3 text-xs text-slate-500">
      </div>
    </div>
  );
}
